(()=>{const init=()=>{const W=window.FormenWebGL;if(!W.renderer)return;const resize=()=>{W.camera.aspect=innerWidth/innerHeight;W.camera.updateProjectionMatrix();W.renderer.setSize(innerWidth,innerHeight)};addEventListener('resize',resize,{passive:true});resize()};if(window.FormenWebGL?.renderer)init();else window.addEventListener('formen:webgl-ready',init,{once:true})})();